            long n = sc.nextLong();
            long tmp = n, sum = 0;
            while (tmp > 0) { sum += tmp % 10; tmp /= 10; }
            if (sum > 0 && n % sum == 0) System.out.println(n / sum);
            else System.out.println("0");
        }
    }
}

